insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('panini-select-2025-26-value-box', 'Panini Select 2025-26', 'value_box'::public.product_type, '6 sobres de 4 tarjetas (24)', 550, null, true, false, 'Panini Select Road to FIFA World Cup 2025-26 – Blaster / Value Box (24 tarjetas)', 'Caja Value (Blaster) oficial de Panini Select Road to FIFA World Cup 2025-26, sellada de fábrica: 6 sobres de 4 tarjetas, 24 tarjetas de fútbol coleccionables rumbo al Mundial 2026, con jugadores de 30 selecciones nacionales. En promedio cada caja trae 3 insertos o paralelos, 3 paralelos Purple Mojo y 1 paralelo Pink u Orange Mojo. Colecciona la base de 250 tarjetas en tres niveles de rareza (Terrace, Mezzanine y Field Level), los insertos Equalizers, Select Future, Unstoppable y Snapshots, y busca la Black Mojo 1/1 exclusiva de Blaster. Puede traer autógrafos (no garantizados), incluidos los Blue Pulsar Autographs exclusivos de Blaster y Mega, con firmantes como Lionel Messi, Kylian Mbappé, Erling Haaland y Neymar Jr. Tarjetas Panini originales en Guatemala con El Coleccionista.', 6, 4, '{}'::text[], null, 'selecciones', '[]'::jsonb, '', '', '', 0) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/select-blaster.webp', 'Caja sellada Panini Select 2025-26, value box', 'frente', 0 from public.products where slug = 'panini-select-2025-26-value-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('topps-chrome-bundesliga-2025-26-value-box', 'Topps Chrome Bundesliga 2025/26', 'value_box'::public.product_type, '7 sobres de 4 tarjetas (28)', 550, null, true, false, 'Topps Chrome Bundesliga 2025/26 – Value Box (7 sobres, 28 tarjetas)', 'Value Box oficial de Topps Chrome Bundesliga 2025/26, sellada de fábrica: 7 sobres de 4 tarjetas, 28 tarjetas cromadas de la liga alemana con estrellas del Bayern Múnich, Borussia Dortmund, Bayer Leverkusen y más, además de novatos (rookies) como Jobe Bellingham, Lennart Karl y Luka Vušković. En promedio cada caja trae 4 paralelos Pulsar Refractor exclusivos de Value, 1 tarjeta Black Spektrum, 1 paralelo numerado y 6 insertos. Busca insertos Electrified, Illumination, Ornaments y Wild Jungle, los case hits Anime, Helix y Shadow Etch, y autógrafos que salen en cajas de la suerte (no garantizados). Tarjetas Topps Chrome originales en Guatemala con El Coleccionista.', 7, 4, '{}'::text[], null, 'ligas_europeas', '[]'::jsonb, '', '', '', 10) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/chrome-bundesliga.webp', 'Caja sellada Topps Chrome Bundesliga 2025/26, value box', 'frente', 0 from public.products where slug = 'topps-chrome-bundesliga-2025-26-value-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('topps-chrome-uefa-2025-26-value-box', 'Topps Chrome UEFA 2025/26', 'value_box'::public.product_type, '7 sobres de 4 tarjetas · 4 paralelas Raywave', 550, null, true, false, 'Topps Chrome UEFA Club Competitions 2025/26 – Value Box (Champions League)', 'Value Box oficial de Topps Chrome UEFA Club Competitions 2025/26 (UCC), sellada de fábrica: 7 sobres de 4 tarjetas, 28 tarjetas cromadas de la UEFA Champions League, Europa League y Conference League. Base de 200 tarjetas con veteranos, leyendas y los rookies más esperados. Cada caja incluye paralelos Raywave exclusivos de Value, 1 paralelo numerado y 3 insertos en promedio. Busca el case hit Bionic, exclusivo de Value Box, que reimagina a los jugadores como robots, insertos como Wonderkids y Power Players, y autógrafos (incluidos on-card) que aparecen en cajas de la suerte (no garantizados). Tarjetas Topps Chrome de Champions League originales en Guatemala con El Coleccionista.', 7, 4, '{}'::text[], null, 'ligas_europeas', '[]'::jsonb, '', '', '', 20) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/chrome-uefa.webp', 'Caja sellada Topps Chrome UEFA 2025/26, value box', 'frente', 0 from public.products where slug = 'topps-chrome-uefa-2025-26-value-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('topps-merlin-premier-league-2026-value-box', 'Topps Merlin Premier League 2026', 'value_box'::public.product_type, '7 sobres de 4 tarjetas · 2 insertos TA-DA', 550, null, true, false, 'Topps Merlin Premier League 2026 – Value Box (7 sobres, 28 tarjetas)', 'Value Box oficial de Topps Merlin Premier League 2026 (temporada 2025/26), sellada de fábrica: 7 sobres de 4 tarjetas, 28 tarjetas cromadas de la Premier League inglesa con el estilo clásico de Merlin. En promedio cada caja trae 2 insertos Ta-Da exclusivos de Value, 3 paralelos Raywave exclusivos, 2 Refractors, 1 VHS Refractor, 1 paralelo numerado y 3 insertos comunes (Fantasy Football, Mystic Afternoons, Merlin''s Young Magicians y Merlin Speaks). Busca el short print Rainbow Flick exclusivo de Value Box, las variantes Merlin 1996, los SP Magic In His Boots y Merlin''s Magnum Opus, y los insertos Renaissance y The Shiny. Autógrafos posibles, no garantizados. Tarjetas de Premier League originales en Guatemala con El Coleccionista.', 7, 4, '{}'::text[], null, 'ligas_europeas', '[]'::jsonb, '', '', '', 30) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/merlin-pl.webp', 'Caja sellada Topps Merlin Premier League 2026, value box', 'frente', 0 from public.products where slug = 'topps-merlin-premier-league-2026-value-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('topps-premier-league-flagship-2026-27-value-box', 'Topps Premier League Flagship 2026/27', 'value_box'::public.product_type, '6 sobres de 10 tarjetas · 4 Green Voltage y 2 Mayhem', 550, null, true, false, 'Topps Flagship Premier League 2026/27 – Value Box (6 sobres, 60 tarjetas)', 'Value Box oficial de Topps Flagship Premier League 2026/27, sellada de fábrica: 6 sobres de 10 tarjetas, 60 tarjetas de la Premier League inglesa de la temporada más reciente, con los 20 clubes, estrellas como Erling Haaland y Bukayo Saka y rookies como Rayan y JJ Gabriel. Base de 300 tarjetas (280 base + 20 Future Stars, nuevas en Flagship). Cada caja incluye 4 paralelos Green Voltage y 2 insertos Mayhem, ambos exclusivos de Value Box, y en promedio 1 paralelo numerado cada 2 cajas. Busca los Mayhem Autographs, los short prints All Kings, ULTRA Beast Mode y Diamond Rookies, y autografías de estrellas y leyendas (no garantizadas). Tarjetas Topps de Premier League originales en Guatemala con El Coleccionista.', 6, 10, '{}'::text[], null, 'ligas_europeas', '[]'::jsonb, '', '', '', 40) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/topps-pl-flagship.webp', 'Caja sellada Topps Premier League Flagship 2026/27, value box', 'frente', 0 from public.products where slug = 'topps-premier-league-flagship-2026-27-value-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('panini-prizm-fifa-world-cup-2026-mega-box', 'Panini Prizm FIFA World Cup 2026', 'mega_box'::public.product_type, '6 sobres de 7 tarjetas (42)', 750, null, true, false, 'Panini Prizm FIFA World Cup 2026 – Mega Box (6 sobres, 42 tarjetas)', 'Mega Box oficial de Panini Prizm FIFA World Cup 2026, sellada de fábrica: 6 sobres de 7 tarjetas, 42 tarjetas de fútbol del Mundial 2026 con las 48 selecciones clasificadas. En promedio cada caja trae 1 Prizm numerado, 1 Silver Prizm, 6 Prizms adicionales (incluidos los paralelos Disco exclusivos de Mega Box), 1 inserto Silver y 5 insertos o paralelos de inserto. Colecciona los insertos Scorers Club, New Era, Connections, Aces, Phenomenon, Global Reach, Trophy Hunting y Screamers, y busca el súper raro Color Blast, que debuta en un Mundial. Puede traer autógrafos (no garantizados) de líneas como Signature Moments, Quad Signatures y National Heroes. Tarjetas Panini Prizm del Mundial originales en Guatemala con El Coleccionista.', 6, 7, '{}'::text[], null, 'selecciones', '[]'::jsonb, '', '', '', 50) on conflict (slug) do nothing;
insert into public.product_images (product_id, storage_path, alt, kind, position) select id, '/catalog/boxes/prizm-mega.webp', 'Caja sellada Panini Prizm FIFA World Cup 2026, mega box', 'frente', 0 from public.products where slug = 'panini-prizm-fifa-world-cup-2026-mega-box' and not exists (select 1 from public.product_images pi where pi.product_id = products.id);
insert into public.products (slug, name, type, short_detail, price_gtq, stock, published, featured, seo_title, seo_description, packs, cards_per_pack, tags, combo_category, competition, specs, story_title, story_note, story_body, sort_order) values ('panini-select-2025-26-mega-box', 'Panini Select 2025-26', 'mega_box'::public.product_type, '6 sobres de 10 tarjetas (60)', 750, null, true, false, 'Panini Select Road to FIFA World Cup 2025-26 – Mega Box (6 sobres, 60 tarjetas)', 'Mega Box oficial de Panini Select Road to FIFA World Cup 2025-26, sellada de fábrica: 6 sobres de 10 tarjetas, 60 tarjetas de fútbol rumbo al Mundial 2026 con 30 selecciones nacionales. En promedio cada caja trae 12 paralelos Ice exclusivos de Mega, 2 paralelos numerados (como el Blue Ice /125) y 6 insertos o paralelos. Colecciona la base de 250 tarjetas en tres niveles (Terrace, Mezzanine y Field Level), los insertos Equalizers, Select Future, Unstoppable y Snapshots, y busca autógrafos (no garantizados) como Select Stars Signatures, Select Pairings y los Blue Pulsar Autographs exclusivos de Blaster y Mega, con firmantes como Messi, Mbappé, Haaland y Neymar Jr. Tarjetas Panini Select originales en Guatemala con El Coleccionista.', 6, 10, '{}'::text[], null, 'selecciones', '[]'::jsonb, '', '', '', 60) on conflict (slug) do nothing;
